"""RoboLab standard-mode mustard-to-left-bin controller for eai-standard/2.2."""
import json, sys, time, pathlib
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

OUT = pathlib.Path('/app/runs/mustard_left_bin')
OUT.mkdir(parents=True, exist_ok=True)
# Calibrated from the static mirrored camera and depth: bottle centre x=.62, y=0;
# robot-left (+y) bin opening centre approximately x=.53, y=.29.
DOWN = np.array([0.0, -0.70710678, 0.70710678, 0.0], dtype=float)
BOTTLE_XY = (0.62, 0.0)
BIN_XY = (0.53, 0.29)

def robot():
    return Robot()

def status(r):
    s = r.status(); print('STATUS', json.dumps(s), flush=True); return s

def pose_now(r):
    o = r.get_obs(cameras=[], video='none')
    return np.asarray(o.meta['proprio']['now'], dtype=float)[8:15]

def move(r, name, xyz, grip, idx):
    p = np.array([*xyz, *DOWN, float(grip)], dtype=np.float32)
    res = r.submit('ee_pose', p[None, :], video='both', video_fps=3, note=name)
    res.save(str(OUT / f'{idx:02d}_{name}'))
    print('MOVE', name, 'target', p.tolist(), 'plan', json.dumps(res.meta.get('plan')), 'done', res.done,
          'steps', res.meta.get('control_steps_chunk'), 'current_tcp', pose_now(r).tolist(), flush=True)
    status(r)
    if res.done: return
    return res

def run(stage):
    r = robot()
    status(r)
    if stage == 'approach':
        move(r, 'above_bottle', (BOTTLE_XY[0], BOTTLE_XY[1], 0.31), 0, 1)
    elif stage == 'grasp':
        move(r, 'grasp_bottle', (BOTTLE_XY[0], BOTTLE_XY[1], 0.115), 0, 2)
        if not r.status().get('done'):
            # Close at the bottle's broad waist; the binary gripper command is applied on this row.
            move(r, 'close_gripper', (BOTTLE_XY[0], BOTTLE_XY[1], 0.115), 1, 3)
    elif stage == 'lift':
        move(r, 'lift_bottle', (BOTTLE_XY[0], BOTTLE_XY[1], 0.34), 1, 4)
    elif stage == 'transfer':
        move(r, 'above_left_bin', (BIN_XY[0], BIN_XY[1], 0.34), 1, 5)
    elif stage == 'place':
        move(r, 'lower_into_left_bin', (BIN_XY[0], BIN_XY[1], 0.115), 1, 6)
        if not r.status().get('done'):
            move(r, 'release_bottle', (BIN_XY[0], BIN_XY[1], 0.115), 0, 7)
    elif stage == 'retreat':
        move(r, 'retreat', (BIN_XY[0], BIN_XY[1], 0.34), 0, 8)
    elif stage == 'observe':
        o = r.get_obs(depth=True)
        for cam, im in o.last.items():
            from PIL import Image
            Image.fromarray(im).save(str(OUT / f'observe_{cam}.png'))
        print('PROPRIO', json.dumps(o.meta['proprio']), flush=True)
    else:
        raise SystemExit('stage must be approach, grasp, lift, transfer, place, retreat, or observe')

if __name__ == '__main__':
    run(sys.argv[1] if len(sys.argv) > 1 else 'observe')
